package main

import "fmt"

func main() {
	done := make(chan struct{})

	// go 只是把任务交给运行时，main 不会停下来等它跑完。
	go func() {
		total := 0
		for i := 1; i <= 100; i++ {
			total += i
		}
		fmt.Println("子任务结果:", total)
		// 干完就关闭 done：close 是广播，等待方立刻被唤醒。
		close(done)
	}()

	// 没有 sync.WaitGroup，就用「等通道」代替「等签到表」。
	<-done
	fmt.Println("main: 子任务已完成，安全退出")
}

