package main

import "fmt"

func main() {
	left := make(chan int)
	right := make(chan int)

	// 无缓冲通道：没人接收时，发送方会一直阻塞在发送这一行。
	go func() {
		left <- 101
	}()
	go func() {
		right <- 202
	}()

	// 按 left、right 的固定顺序接收：谁先发完都不影响打印顺序。
	fmt.Println("先收:", <-left)
	fmt.Println("后收:", <-right)
}

