package main

import "fmt"

func main() {
	// 容量 3：缓冲区没满时，发送方不必等接收方到场。
	ch := make(chan int, 3)
	ch <- 10
	ch <- 20
	ch <- 30
	fmt.Println("缓冲区占用:", len(ch), "容量:", cap(ch))

	// 关闭后 range 会把缓冲里剩下的数据取完再结束，不会一直等。
	close(ch)

	sum := 0
	for v := range ch {
		sum += v
	}
	fmt.Println("总和:", sum)
	fmt.Println("取完后占用:", len(ch))
}

package main

import "fmt"

func main() {
	results := make(chan int, 2)
	done := make(chan struct{}) // 一直不关闭：本次任务没有被取消

	// 生产者写完两个结果就关闭通道，表示不会再有数据了。
	go func() {
		results <- 3
		results <- 4
		close(results)
	}()

	total := 0
loop:
	// 循环上界故意给大：真正的结束条件由 ok 决定，而不是数数。
	for i := 0; i < 5; i++ {
		select {
		case v, ok := <-results:
			if !ok {
				fmt.Println("数据已取完，退出")
				break loop // select 里的 break 只跳出 select，跳出 for 要加标签
			}
			total += v
		case <-done:
			fmt.Println("收到取消信号")
			break loop
		}
	}
	fmt.Println("合计:", total)
}

