package main

import "fmt"

type Result struct{ JobID, Value int }

// worker 从 jobs 连续取任务：jobs 关闭后 range 结束，worker 才退出。
func worker(jobs <-chan int, results chan<- Result) {
	for job := range jobs {
		results <- Result{JobID: job, Value: job * job}
	}
}

func main() {
	jobs := make(chan int, 4)
	results := make(chan Result, 4)
	for w := 1; w <= 2; w++ {
		go worker(jobs, results)
	}
	for j := 1; j <= 4; j++ {
		jobs <- j
	}
	close(jobs) // 任务发完就关闭，worker 干完手里的活会自己退出

	// 完成顺序由调度决定，先按 JobID 归位，输出才和并发快慢无关。
	values := make([]int, 4)
	for i := 0; i < 4; i++ {
		r := <-results
		values[r.JobID-1] = r.Value
	}
	for i, v := range values {
		fmt.Printf("任务 %d 的平方: %d\n", i+1, v)
	}
}

