package main

import "fmt"

// guarded 是带取消能力的阶段：done 关闭后在下一轮检查时退出。
// 注意取消是协作式的：已经进入发送的那个元素仍会送达，下游要能排空。
func guarded(in <-chan int, factor int, done <-chan struct{}) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			select {
			case <-done:
				return
			default:
				out <- n * factor
			}
		}
	}()
	return out
}

// relay 是纯接力阶段：没有取消分支，读完上游后关闭自己的下游。
func relay(in <-chan int, factor int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			out <- n * factor
		}
	}()
	return out
}

func main() {
	nums := make(chan int, 4)
	for n := 1; n <= 4; n++ {
		nums <- n
	}
	close(nums) // 上游关闭后，下游 range 取完 4 个元素就会结束

	done := make(chan struct{}) // 本次不关闭：先看完整的流水线
	doubled := guarded(nums, 2, done)
	for v := range relay(doubled, 10) {
		fmt.Println(v)
	}
	fmt.Println("流水线结束")
}

